import{_ as i,a0 as s,w as a,s as d,I as e,x as o,a1 as p,A as r,ao as l}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const T=JSON.parse('{"title":"Conky - 终极的 X 视窗系统监视器应用 | LCTT x X-CMD","titleTemplate":false,"description":"Conky - 终极的 X 视窗系统监视器应用 | LCTT (201505) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Conky - 终极的 X 视窗系统监视器应用 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Conky - 终极的 X 视窗系统监视器应用 | LCTT (201505) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201505/20150331 Conky--The Ultimate X Based System Monitor Application","title":"Conky - 终极的 X 视窗系统监视器应用","tag":"201505","desc":""},"relativePath":"201505/20150331 Conky--The Ultimate X Based System Monitor Application.md","filePath":"[post].md"}'),u={name:"201505/20150331 Conky--The Ultimate X Based System Monitor Application.md"};function y(k,t,m,c,C,f){const n=s("Link");return a(),d("div",null,[t[26]||(t[26]=e("h1",{id:"conky-终极的-x-视窗系统监视器应用",tabindex:"-1"},[o("Conky - 终极的 X 视窗系统监视器应用 "),e("a",{class:"header-anchor",href:"#conky-终极的-x-视窗系统监视器应用","aria-label":"Permalink to “Conky - 终极的 X 视窗系统监视器应用”"},"​")],-1)),e("p",null,[t[1]||(t[1]=o("Conky 是一个用 ‘C’ 语言写就的系统监视器，并在 GNU GPL 和 BSD 许可协议下发布，在 Linux 和 BSD 操作系统中都可以获取到它。这个应用是基于 X 视窗系统的，原本由 ",-1)),p(n,{href:"http://torsmo.sourceforge.net/"},{default:r(()=>[...t[0]||(t[0]=[o("Torsmo",-1)])]),_:1}),t[2]||(t[2]=o(" 分支而来。",-1))]),t[27]||(t[27]=l(`<h4 id="特点" tabindex="-1">特点 <a class="header-anchor" href="#特点" aria-label="Permalink to “特点”">​</a></h4><ul><li>简洁的用户界面;</li><li>高度可配置;</li><li>它既可使用内置的部件(超过 300 多个) 也可使用外部脚本，来在桌面或其自有容器中展示系统的状态；</li><li>低资源消耗;</li><li>它可显示范围广泛的系统参数，包括但不限于 CPU，内存，swap 分区 ，温度，进程，磁盘使用情况，网络状态，电池电量，邮件收发，系统消息，音乐播放器的控制，天气信息，最新新闻，升级信息等等；</li><li>在许多操作系统中如 CrunchBang Linux 和 Pinguy OS 被默认安装；</li></ul><h4 id="关于-conky-的少有人知的事实" tabindex="-1">关于 Conky 的少有人知的事实 <a class="header-anchor" href="#关于-conky-的少有人知的事实" aria-label="Permalink to “关于 Conky 的少有人知的事实”">​</a></h4><ul><li>conky 这个名称来自于一个加拿大电视节目；</li><li>它已被移植到 Nokia N900 上；</li><li>官方已经不再维护它了；</li></ul><h3 id="在-linux-中-conky-的安装和使用" tabindex="-1">在 Linux 中 Conky 的安装和使用 <a class="header-anchor" href="#在-linux-中-conky-的安装和使用" aria-label="Permalink to “在 Linux 中 Conky 的安装和使用”">​</a></h3><p>在我们安装 conky 之前，我们需要使用下面的命令来安装诸如 <code>lm-sensors</code>, <code>curl</code> 和 <code>hddtemp</code> 之类的软件包：</p><pre><code># apt-get install lm-sensors curl hddtemp
</code></pre><p>然后是检测传感器：</p><pre><code># sensors-detect
</code></pre><p><strong>注</strong>: 在被系统提示时，回答 ‘Yes’ 。</p><p>检测所有探测到的传感器：</p><pre><code># sensors
</code></pre><h4 id="样例输出" tabindex="-1">样例输出 <a class="header-anchor" href="#样例输出" aria-label="Permalink to “样例输出”">​</a></h4><pre><code>acpitz-virtual-0
Adapter: Virtual device
temp1:        +49.5°C  (crit = +99.0°C)

coretemp-isa-0000
Adapter: ISA adapter
Physical id 0:  +49.0°C  (high = +100.0°C, crit = +100.0°C)
Core 0:         +49.0°C  (high = +100.0°C, crit = +100.0°C)
Core 1:         +49.0°C  (high = +100.0°C, crit = +100.0°C)
</code></pre><p>Conky 既可以从软件仓库中安装，也可从源代码编译得到：</p><pre><code># yum install conky              [在 RedHat 系的系统上]
# apt-get install conky-all      [在 Debian 系的系统上]
</code></pre>`,16)),e("p",null,[t[4]||(t[4]=e("strong",null,"注",-1)),t[5]||(t[5]=o(": 在 Fedora/CentOS 上安装 conky 之前，你必须启用 ",-1)),p(n,{href:"https://linux.cn/article-2324-1.html"},{default:r(()=>[...t[3]||(t[3]=[o("EPEL 软件仓库",-1)])]),_:1}),t[6]||(t[6]=o("。",-1))]),t[28]||(t[28]=l(`<p>在安装完 conky 之后，只需输入如下命令来开启它：</p><pre><code>$ conky &amp;
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/03/Start-Conkey.jpeg" alt="正在运行的 Conky 监视器"></p><p><em>正在运行的 Conky 监视器</em></p><p>这使得 conky 以一个弹窗的形式运行，并使用位于 <code>/etc/conky/conky.conf</code> 的 conky 基本配置文件。</p><p>你可能想将 conky 集成到桌面上，并不想让它每次以弹窗的形式出现，下面就是你需要做的：</p><p>将配置文件 <code>/etc/conky/conky.conf</code> 复制到你的家目录中，并将它重命名为 <code>.conkyrc</code>，开头的点号 (.) 是为了确保这个配置文件是隐藏的。</p><pre><code>$ cp /etc/conky/conky.conf /home/$USER/.conkyrc
</code></pre><p>现在重启 conky 来应用新的更改：</p><pre><code>$ killall -SIGUSR1 conky
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/03/Restart-Conky.jpeg" alt="Conky 监视器窗口"></p><p><em>Conky 监视器窗口</em></p><p>你可能想编辑位于你的家目录的 conky 的配置文件，这个配置文件的内容是非常容易理解的。</p><p>下面是 conky 配置文件的一个样例：</p><p><img src="http://www.tecmint.com/wp-content/uploads/2015/03/Conky-Configuration.jpeg" alt="Conky 的配置"></p><p><em>Conky 的配置</em></p><p>从上面的窗口中，你可以更改颜色，边框，大小，缩放比例，背景，对齐方式及几个其他属性。通过为不同的 conky 窗口设定不同的对齐方式，我们可以同时运行几个 conky 脚本。</p><p><strong>让 conky 使用其它脚本而不是默认配置，以及如何找到这些脚本？</strong></p><p>你可以编写你自己的 conky 脚本或使用来自于互联网的脚本；我们并不建议你使用从互联网中找到的具有潜在危险的任何脚本，除非你清楚你正在做什么。然而，有一些著名的主题和网页包含可信赖的 conky 脚本，例如下面所提及的：</p>`,19)),e("ul",null,[e("li",null,[p(n,{href:"http://ubuntuforums.org/showthread.php?t=281865"},{default:r(()=>[...t[7]||(t[7]=[o("http://ubuntuforums.org/showthread.php?t=281865",-1)])]),_:1})]),e("li",null,[p(n,{href:"http://conky.sourceforge.net/screenshots.html"},{default:r(()=>[...t[8]||(t[8]=[o("http://conky.sourceforge.net/screenshots.html",-1)])]),_:1})])]),t[29]||(t[29]=l(`<p>在上面的 URL 地址中，你将发现其中每个截图都有一个超链接，它们将指向到脚本文件。</p><h4 id="测试-conky-脚本" tabindex="-1">测试 Conky 脚本 <a class="header-anchor" href="#测试-conky-脚本" aria-label="Permalink to “测试 Conky 脚本”">​</a></h4><p>这里我将在我的 Debian Jessie 系统中运行一个由第三方写的 conky 脚本，以此来进行测试：</p><pre><code>$ wget https://github.com/alexbel/conky/archive/master.zip
$ unzip master.zip 
</code></pre><p>切换当前工作目录到刚才解压的目录：</p><pre><code>$ cd conky-master
</code></pre><p>将 <code>secrets.yml.example</code> 重命名为 <code>secrets.yml</code>：</p><pre><code>$ mv secrets.yml.example secrets.yml
</code></pre><p>在你需要运行这个(ruby)脚本之前安装 Ruby：</p><pre><code>$ sudo apt-get install ruby
$ ruby starter.rb 
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/03/Conky-Fancy-Look.jpeg" alt="华丽的 conky 外观"></p><p><em>华丽的 conky 外观</em></p><p><strong>注</strong>: 可以修改这个脚本以展示你当前的天气，温度等；</p><p>假如你想让 conky 开机自启，请在开机启动应用设置(startup Applications) 中添加如下的几行命令：</p><pre><code>conky --pause 10 
save and exit.
</code></pre>`,15)),e("p",null,[t[10]||(t[10]=o("最后，如此轻量级且吸引眼球的实用 GUI 软件包不再处于活跃状态且官方不再进行维护了。最新的稳定发布版本为 conky 1.9.0， 于 2012 年 5 月 3 号发布。在 Ubuntu 论坛上，一个有关用户分享 conky 配置的主题已经超过了 2000 多页。(这个论坛主题的链接为: ",-1)),p(n,{href:"http://ubuntuforums.org/showthread.php?t=281865/"},{default:r(()=>[...t[9]||(t[9]=[o("http://ubuntuforums.org/showthread.php?t=281865/",-1)])]),_:1}),t[11]||(t[11]=o(")",-1))]),e("ul",null,[e("li",null,[p(n,{href:"http://conky.sourceforge.net/"},{default:r(()=>[...t[12]||(t[12]=[o("Conky 主页",-1)])]),_:1})])]),t[30]||(t[30]=e("p",null,"这就是全部内容了。保持联系，保持评论。请在下面的评论框里分享你的想法和配置。",-1)),t[31]||(t[31]=e("hr",null,null,-1)),e("p",null,[t[14]||(t[14]=o("via: ",-1)),p(n,{href:"http://www.tecmint.com/install-conky-in-ubuntu-debian-fedora/"},{default:r(()=>[...t[13]||(t[13]=[o("http://www.tecmint.com/install-conky-in-ubuntu-debian-fedora/",-1)])]),_:1})]),e("p",null,[t[18]||(t[18]=o("作者：",-1)),p(n,{href:"http://www.tecmint.com/author/avishek/"},{default:r(()=>[...t[15]||(t[15]=[o("Avishek Kumar",-1)])]),_:1}),t[19]||(t[19]=o(" 译者：",-1)),p(n,{href:"https://github.com/FSSlc"},{default:r(()=>[...t[16]||(t[16]=[o("FSSlc",-1)])]),_:1}),t[20]||(t[20]=o(" 校对：",-1)),p(n,{href:"https://github.com/wxy"},{default:r(()=>[...t[17]||(t[17]=[o("wxy",-1)])]),_:1})]),e("p",null,[t[23]||(t[23]=o("本文由 ",-1)),p(n,{href:"https://github.com/LCTT/TranslateProject"},{default:r(()=>[...t[21]||(t[21]=[o("LCTT",-1)])]),_:1}),t[24]||(t[24]=o(" 原创翻译，",-1)),p(n,{href:"http://linux.cn/"},{default:r(()=>[...t[22]||(t[22]=[o("Linux中国",-1)])]),_:1}),t[25]||(t[25]=o(" 荣誉推出",-1))])])}const w=i(u,[["render",y]]);export{T as __pageData,w as default};
